export const FIELD_POSITIONS=[['Keeper',0,6],['First slip',-2.5,5],['Second slip',-5,4],['Point',-17,-3],['Cover',-23,-22],['Mid-off',-14,-39],['Mid-on',14,-39],['Midwicket',24,-20],['Fine leg',25,27],['Third man',-31,25]];
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
// Deterministic field movement and running, driven by the same simulation clock.
export class FieldingController {
 constructor(){this.actors=FIELD_POSITIONS.map(([name,x,z],i)=>({name,x,z,vx:0,vz:0,speed:i===0?5:6.2+(i%3)*.3,reaction:.23+i*.018,phase:'ready',distance:0}));this.elapsed=0;this.requestedRuns=0;this.runs=0;this.runProgress=0;this.possession=null;this.returning=false;this.hold=0;}
 requestRun(){if(this.possession===null&&!this.returning)this.requestedRuns=Math.min(4,this.requestedRuns+1);}
 step(sim,dt){this.elapsed+=dt;const ball=sim.position;if(sim.contact&&this.runs<this.requestedRuns){this.runProgress+=dt*5.7/20.12;if(this.runProgress>=1){this.runProgress-=1;this.runs++;sim.event('RunCompleted',{runs:this.runs});}}
 if(this.possession!==null&&!this.returning){const f=this.actors[this.possession];this.hold+=dt;sim.position={x:f.x,y:.9,z:f.z};sim.velocity={x:0,y:0,z:0};f.phase=this.hold<.35?'pickup':'throw';if(this.hold>.55){const dx=-f.x,dz=1-f.z,t=Math.max(.15,Math.hypot(dx,dz)/24);sim.velocity={x:dx/t,y:(.65-.9+.5*9.81*t*t)/t,z:dz/t};this.returning=true;this.returnAt=this.elapsed+t;sim.event('FielderThrow',{fielder:f.name,position:sim.position,velocity:sim.velocity});}return;}
 if(this.returning){const atWicket=Math.hypot(ball.x,ball.z-1)<1.3&&ball.y<1.5;if(this.elapsed>=this.returnAt&&(atWicket||this.elapsed>this.returnAt+.5)){const runout=atWicket&&this.runProgress>.05&&this.runProgress<.96;sim.event(runout?'RunOut':'FieldingComplete',{runs:this.runs,position:sim.position});sim.end(runout?'RUN OUT':this.runs?this.runs+' RUN'+(this.runs===1?'':'S'):'DOT BALL');}return;}
 let closest=-1,best=Infinity;for(let i=0;i<this.actors.length;i++){const f=this.actors[i],d=Math.hypot(ball.x-f.x,ball.z-f.z);if(d<best){best=d;closest=i;}}
 for(let i=0;i<this.actors.length;i++){const f=this.actors[i],react=sim.contact?sim.time-sim.contact.timeS>f.reaction:i===0&&ball.z>0;if(!react||sim.dead)continue;const pursuing=i===closest||i===0,tx=ball.x+sim.velocity.x*.12,tz=i===0&&!sim.contact?6:ball.z+sim.velocity.z*.12,dx=tx-f.x,dz=tz-f.z,d=Math.hypot(dx,dz),targetSpeed=pursuing?Math.min(f.speed,d*4):0,ux=d?dx/d:0,uz=d?dz/d:0,alpha=Math.min(1,dt*6);f.vx+=(ux*targetSpeed-f.vx)*alpha;f.vz+=(uz*targetSpeed-f.vz)*alpha;f.x+=f.vx*dt;f.z+=f.vz*dt;f.distance+=Math.hypot(f.vx,f.vz)*dt;f.phase=targetSpeed>1?'run':'ready';
 const reach=i===0?.72:.58,dist=Math.hypot(ball.x-f.x,ball.z-f.z);if(dist<reach&&ball.y<2.5&&ball.y>0){if(sim.contact&&sim.postHitBounces===0){f.phase='catch';sim.event('Caught',{fielder:f.name,position:ball});sim.end('CAUGHT');return;}if(!sim.contact){f.phase='collect';sim.event('KeeperCollected',{position:ball});sim.end('MISSED');return;}if(ball.y<.5){this.possession=i;f.phase='pickup';sim.event('FielderPickup',{fielder:f.name,position:ball});return;}}}
 }
 snapshot(){return {actors:this.actors.map(({name,x,z,vx,vz,phase,distance})=>({name,x,z,vx,vz,phase,distance})),runs:this.runs,runProgress:this.runProgress,requestedRuns:this.requestedRuns,returning:this.returning};}
}
